sys_script_include.script:
var ContrastAppListIntegrationJson = Class.create();
ContrastAppListIntegrationJson.prototype = Object.extendsObject(sn_vul.ApplicationVulnerabilityIntegrationBase, {

    UTIL: new x_ntsi_contrast_ap.ContrastUtilBase(),

    retrieveData: function() {
        var offset = 0;
        var limit = 2000;
        var arr = [];
        var responseBody = -1;
        var rtn = true;
        while (rtn == true) {

            var resp = this.UTIL.triggerAPI(this.IMPLEMENTATION, offset, limit);
            if (resp.getStatusCode() != 200) {
                gs.error("API Failed with status code: " + resp.getStatusCode());
                break;
            }
            var apps = JSON.parse(resp.getBody());
            responseBody = apps.applications.length;
            var application_parms = apps.applications || [];
            if (application_parms.length === 0) break;
            var orgID = new x_ntsi_contrast_ap.ContrastUtilBase().getApiORGDetails();
            var appURL = new x_ntsi_contrast_ap.ContrastUtilBase().getApiURLDetails();

            for (var appIdx in application_parms) {

                var offset_v = 0;
                var limit_v = 50;
                var app = application_parms[appIdx];

                while (rtn == true) {
                    var vulresp = this.UTIL.getIASTVulnerabilities(this.IMPLEMENTATION, app.app_id, offset_v, limit_v);
                    if (vulresp.getStatusCode() != 200){
						gs.error("API Failed with status code: " + vulresp.getStatusCode());
						break;
					}

                    var vul = JSON.parse(vulresp.getBody());
                    var traces = vul.traces || [];
					if (traces.length === 0) break;

                    for (var tIdx in traces) {
                        var trace = traces[tIdx];
                        trace.app_id = app.app_id;
                        trace.app_name = app.name;
                        trace.app_version = (trace.app_version_tags || []).toString();
                        trace.organization_id = orgID;
                        trace.source_link = "https://" + appURL + "/Contrast/static/ng/index.html#/" + orgID + "/applications/" + app.app_id + "/vulns/" + trace.uuid;
                        trace.vul_link = "https://" + appURL + "/Contrast/api/ng/" + orgID + "/orgtraces/mark";
                        arr.push(trace);                      
                    }
					offset_v += limit_v;
                }
            }
            offset += limit;
        }

        var objtraces = {
            "traces": arr
        };

        var attachmentGr = new GlideSysAttachment();
        var fileName = this.integrationGr.name + "_" + new GlideDateTime().toString() + ".json";
        var sysId = attachmentGr.write(this.integrationProcessGr, fileName, "json", JSON.stringify(objtraces));

        return {
            contents: sysId,
            contentType: "sys_attachment",
            extension: "json"
        };
    },

    shouldRetry: function(process) {
        return true;
    },

    type: 'ContrastAppListIntegrationJson'
});
